((window.CARDS_BY_LANG = window.CARDS_BY_LANG || {}).en = window.CARDS_BY_LANG.en || {}).animal = [{"name":"Lion","emoji":"🦁","meta":["mammal","African savannah","males up to 250 kg"],"description":"The only cat that lives in large family groups called prides, where the lionesses do most of the hunting. A male's thick mane is a sign of strength and status, and its colour darkens with age. In many cultures the lion has long stood for power and courage.","fact":"A lion's roar carries up to eight kilometres and serves to guard the pride's territory.","wiki_en":"Lion"},{"name":"Tiger","emoji":"🐅","meta":["mammal","forests and jungles of Asia","the largest cat"],"description":"The biggest of the wild cats, marked by a pattern of stripes that is unique to every animal, like a fingerprint. Unlike most cats, the tiger is a strong swimmer and genuinely enjoys water. Nearly all of its surviving subspecies are now endangered.","fact":"A tiger's stripes are not only on its fur but on its skin as well, so the pattern stays even after shaving.","wiki_en":"Tiger"},{"name":"Leopard","emoji":"🐆","meta":["mammal","Africa and Asia","up to 90 kg"],"description":"A secretive and astonishingly powerful hunter that can haul prey twice its own weight up a tree, out of reach of hyenas and lions. Its spotted coat is perfect camouflage in savannah and forest alike. The leopard has the widest range of any big cat in the world.","fact":"The black panther is not a separate species but a leopard or jaguar with a rare dark coat.","wiki_en":"Leopard"},{"name":"Cheetah","emoji":"💨","meta":["mammal","African savannah","the fastest land animal"],"description":"The fastest land animal on the planet, reaching almost the speed of a sports car over a short sprint. Unlike other big cats it cannot fully retract its claws, which gives it extra grip while running. The black lines under its eyes work like a visor against the sun.","fact":"A cheetah cannot roar: instead it purrs and makes a birdlike chirp to call its cubs.","wiki_en":"Cheetah"},{"name":"Jaguar","emoji":"🐆","meta":["mammal","forests of South America","the strongest cat of the Americas"],"description":"The largest cat of the Western Hemisphere, with one of the most powerful bites of any predator, strong enough to crack a turtle's shell. It often hunts near water and swims well, unlike many other cats. The Maya and the Aztecs revered the jaguar as a sacred animal.","fact":"Unlike most cats, the jaguar often kills its prey with a bite straight through the skull.","wiki_en":"Jaguar"},{"name":"Snow leopard","emoji":"❄️","meta":["mammal","mountains of Central Asia","long tail for balance"],"description":"It lives high in the mountains of Central Asia, where thick fur and broad paws help it endure the cold and move across snow. An extremely long, plush tail works as a balancing pole on cliffs and as a warm wrap during sleep. Because it is so elusive, it is called the ghost of the mountains.","fact":"The snow leopard cannot roar like a lion or a tiger; it mews and hisses instead.","wiki_en":"Snow leopard"},{"name":"Lynx","emoji":"🐈","meta":["mammal","forests of Eurasia and North America","tufted ears"],"description":"A forest cat with distinctive ear tufts and shaggy cheek ruffs that help it catch sounds and sense the wind. Broad paws act like snowshoes, letting it stalk prey silently through deep snow. It hunts mostly alone and prefers an ambush to a chase.","fact":"The tufts on a lynx's ears are thought to help it pick up sounds in the forest more precisely.","wiki_en":"Lynx"},{"name":"African elephant","emoji":"🐘","meta":["mammal","savannahs and forests of Africa","the largest land animal"],"description":"The largest land animal alive, with huge ears that help shed heat in the hot savannah. Its trunk holds tens of thousands of muscles and is used for eating, drinking and communicating alike. Elephants live in complex family groups led by the oldest female.","fact":"Both male and female African elephants usually grow tusks, unlike Asian elephants.","wiki_en":"African elephant"},{"name":"Giraffe","emoji":"🦒","meta":["mammal","African savannah","the tallest animal"],"description":"The tallest land animal on earth, and yet its long neck contains only seven vertebrae, exactly as many as a human neck. The pattern of patches on its coat is unique to each animal, like a fingerprint. Giraffes sleep very little, often in short snatches and standing up.","fact":"The giraffe has one of the longest tongues of any mammal, dark blue in colour to protect it from sunburn.","wiki_en":"Giraffe"},{"name":"Zebra","emoji":"🦓","meta":["mammal","plains of Africa","black and white stripes"],"description":"An African relative of the horse with a striped pattern all its own: no two zebras carry the same one, much like human fingerprints. The stripes are thought to confuse biting insects and predators. Zebras live in herds and have never truly been domesticated.","fact":"What zebra stripes are really for is still debated; one theory is that they keep biting flies away.","wiki_en":"Zebra"},{"name":"Hippopotamus","emoji":"🦛","meta":["mammal","rivers and lakes of Africa","one of the most dangerous animals"],"description":"A semi-aquatic mammal that spends almost the whole day in the water and comes ashore at night to graze. Despite its bulk the hippo runs well over short distances and defends its stretch of river with real aggression. Its skin oozes a pinkish mucus that shields it from sun and infection.","fact":"Hippos are considered among the most dangerous large animals in Africa for humans.","wiki_en":"Hippopotamus"},{"name":"Rhinoceros","emoji":"🦏","meta":["mammal","Africa and Asia","a massive horn of keratin"],"description":"A large thick-skinned animal with one or two horns on its snout, made of keratin, the same protein as human nails and hair. Poaching for those horns has pushed several rhino species to the brink of extinction. A rhino sees poorly but hears and smells superbly.","fact":"A rhino's horn is tightly packed keratin and, unlike the horns of cattle, has no bony core.","wiki_en":"Rhinoceros"},{"name":"Gorilla","emoji":"🦍","meta":["mammal","forests of Central Africa","the largest primate"],"description":"The largest primate alive, and yet mostly a plant eater and surprisingly calm by temperament. A gorilla group is usually led by a mature male whose back turns grey, which is where the term silverback comes from. Gorillas can learn elements of sign language to communicate with people.","fact":"For all its fearsome appearance, a gorilla lives mainly on leaves, stems and fruit.","wiki_en":"Gorilla"},{"name":"Chimpanzee","emoji":"🐵","meta":["mammal","forests of Central and West Africa","a relative of humans"],"description":"One of our closest living relatives, sharing the overwhelming majority of our genome. Chimpanzees use simple tools, sticks and stones, to get at food, and pass those skills on to others. They live in complex social groups with a hierarchy of their own.","fact":"The chimpanzee is one of the few animal species able to recognise itself in a mirror.","wiki_en":"Chimpanzee"},{"name":"Orangutan","emoji":"🦧","meta":["mammal","forests of Borneo and Sumatra","ginger fur"],"description":"A large ginger-haired great ape that spends nearly its whole life in the trees of the Southeast Asian rainforest. Its name comes from Malay and means \"person of the forest\". It is one of the slowest-breeding primates, which makes the species especially vulnerable.","fact":"The word orangutan comes from the Malay words orang, meaning person, and hutan, meaning forest.","wiki_en":"Orangutan"},{"name":"Ring-tailed lemur","emoji":"🐒","meta":["mammal","island of Madagascar","long striped tail"],"description":"One of the most recognisable lemurs of Madagascar thanks to its long black-and-white striped tail, which it cannot use to grip branches. It is active by day and, unlike most lemurs, spends a lot of time on the ground. It lives in troops that females usually dominate.","fact":"Ring-tailed lemurs love to sunbathe, sitting bolt upright with their bellies turned to the light.","wiki_en":"Ring-tailed lemur"},{"name":"Giant panda","emoji":"🐼","meta":["mammal","mountain forests of China","eats mainly bamboo"],"description":"A bear whose diet is almost entirely bamboo, even though its digestive system is that of a carnivore. To take in enough energy it has to eat for many hours every single day. The giant panda is a symbol of China and one of the best known faces of conservation.","fact":"The giant panda has a kind of sixth finger, a wrist bone that helps it grip bamboo stems.","wiki_en":"Giant panda"},{"name":"Red panda","emoji":"🍃","meta":["mammal","mountain forests of the Himalayas","russet fur and a bushy tail"],"description":"A small russet animal with a bushy ringed tail, at home in the mountain forests of the Himalayas and southwest China. Despite the shared name it is no close relative of the giant panda but belongs to a family of its own. Like its namesake it feeds mostly on bamboo shoots.","fact":"The red panda was long shuffled between the raccoon and bear families before being given a family of its own.","wiki_en":"Red panda"},{"name":"Koala","emoji":"🐨","meta":["mammal","eucalyptus forests of Australia","marsupial"],"description":"A marsupial that spends nearly its whole life in eucalyptus trees and eats virtually nothing but their leaves. Eucalyptus is toxic and low in nutrients, so the koala sleeps most of the day to save energy. Like other marsupials it finishes growing in its mother's pouch.","fact":"A koala can tell edible eucalyptus trees by smell, avoiding those with too high a load of toxins.","wiki_en":"Koala"},{"name":"Kangaroo","emoji":"🦘","meta":["mammal","plains of Australia","moves by hopping"],"description":"A large marsupial that travels in powerful bounds on strong hind legs, with a thick tail for support and balance. A joey is born tiny and spends months finishing its growth in its mother's pouch. The kangaroo is one of Australia's defining symbols.","fact":"A kangaroo can barely go backwards: its heavy tail and the build of its hind legs make retreat all but impossible.","wiki_en":"Kangaroo"},{"name":"Platypus","emoji":"🦆","meta":["mammal","rivers of Australia","lays eggs"],"description":"One of the very few mammals on earth that lay eggs: the female lays, then nurses the hatchlings on milk. The platypus has a flat duck-like bill, webbed feet, and in males a venomous spur on the hind leg. It lives in the rivers and streams of eastern Australia.","fact":"Underwater the platypus hunts with its eyes shut, finding prey by the faint electrical signals of their muscles.","wiki_en":"Platypus"},{"name":"Wombat","emoji":"🐾","meta":["mammal","forests and grasslands of Australia","digs deep burrows"],"description":"A stocky marsupial that spends most of its life in branching underground burrows dug with powerful clawed paws. The female's pouch opens backwards so that no soil gets onto the young while she digs. Wombat droppings come out in a distinctive cube shape.","fact":"Cube-shaped droppings help the wombat mark its territory: such bricks do not roll off rocks and logs.","wiki_en":"Wombat"},{"name":"Tasmanian devil","emoji":"😈","meta":["mammal","island of Tasmania","the largest carnivorous marsupial"],"description":"The largest carnivorous marsupial alive, named for its piercing screams and its aggression at a carcass. It survives only on the island of Tasmania, having died out on the Australian mainland. The population has been hit hard by a contagious facial tumour disease.","fact":"European settlers gave the Tasmanian devil its name because of its eerie night-time screams and growls.","wiki_en":"Tasmanian devil"},{"name":"Sloth","emoji":"🦥","meta":["mammal","rainforests of South America","the slowest mammal"],"description":"A slow-moving tree dweller that passes most of its life upside down, hooked to branches by long claws. A sluggish metabolism helps it get by on a thin diet of leaves. Algae often grow in its fur and give the coat a greenish tinge.","fact":"Its slow metabolism means a sloth climbs down to the ground to relieve itself only about once a week.","wiki_en":"Sloth"},{"name":"Capybara","emoji":"🐹","meta":["mammal","wetlands of South America","the largest rodent in the world"],"description":"The largest rodent on the planet, looking much like a giant guinea pig and living closely tied to water. The capybara swims well and can stay submerged for a long stretch to escape predators. It lives in groups and is famous for its remarkably calm, easy-going nature.","fact":"Capybaras are so placid that birds and other small animals routinely perch and rest on top of them.","wiki_en":"Capybara"},{"name":"Giant anteater","emoji":"🐜","meta":["mammal","savannahs and forests of South America","a long toothless snout"],"description":"A large mammal with a long toothless snout and a sticky tongue that can lap up tens of thousands of ants and termites in a day. It walks on the knuckles of its forefeet to keep its powerful claws from blunting. It moves slowly, but when threatened it fights back fiercely.","fact":"A giant anteater's tongue can reach about half a metre and flicks out dozens of times a minute.","wiki_en":"Giant anteater"},{"name":"Armadillo","emoji":"🛡️","meta":["mammal","North and South America","armour of bony plates"],"description":"A mammal whose body is covered by armour made of bony plates, which is exactly what its Spanish name, \"little armoured one\", describes. Some species can roll into a tight ball that no predator's teeth can open. Armadillos dig burrows with strong claws and feed mainly on insects.","fact":"Only three-banded armadillos roll into a tight ball; the shell of the other species will not allow it.","wiki_en":"Armadillo"},{"name":"Alpaca","emoji":"🦙","meta":["mammal","highlands of South America","domesticated for its fleece"],"description":"A domesticated member of the camel family, bred in the Andes above all for its soft, warm fleece. Unlike the llama it is hardly ever used as a pack animal, being smaller and weaker. Alpaca fleece comes in dozens of natural shades, from white to almost black.","fact":"Alpaca fleece is nearly free of lanolin, so it needs little washing before spinning and rarely triggers allergies.","wiki_en":"Alpaca"},{"name":"Camel","emoji":"🐪","meta":["mammal","deserts of Africa and Asia","stores fat in its hump"],"description":"A large hoofed animal built for the desert: its hump stores not water but fat, which can be turned into energy and moisture when needed. Broad feet keep it from sinking into sand, while thick lashes and closeable nostrils fend off sandstorms. A camel can go a long time without drinking.","fact":"After a long thirst a camel can drink more than a hundred litres of water in a few minutes.","wiki_en":"Camel"},{"name":"Brown bear","emoji":"🐻","meta":["mammal","forests of Eurasia and North America","omnivore"],"description":"A large omnivorous predator whose menu shifts with the seasons, from berries and roots to fish and carrion. Before its winter sleep the brown bear lays down a thick layer of fat to get through the cold with almost no food. For all its bulk it can run fast over short distances.","fact":"Over a short distance a brown bear can outrun a sprinting human, heavy body and all.","wiki_en":"Brown bear"},{"name":"Polar bear","emoji":"🐻‍❄️","meta":["mammal","Arctic ice","the largest land predator"],"description":"The largest land predator on the planet, built for life on the Arctic ice, where it hunts mainly seals. Its fur looks white but is in fact colourless and translucent, and the skin beneath it is black, soaking up the sun's heat. It is a strong swimmer that can keep going for hours in freezing water.","fact":"A polar bear's sense of smell is so keen that it finds seals hidden under a layer of snow and ice.","wiki_en":"Polar bear"},{"name":"Wolf","emoji":"🐺","meta":["mammal","forests and tundra of the Northern Hemisphere","lives in packs"],"description":"The ancestor of the domestic dog, living in complex family packs with a strict hierarchy and divided roles on the hunt. Wolves can cover dozens of kilometres in a night looking for prey and keep in touch by howling, which carries a long way. Few animals have gathered as much folklore around them.","fact":"Wolves and domestic dogs are so close genetically that their hybrids are born fertile and can breed.","wiki_en":"Wolf"},{"name":"Red fox","emoji":"🦊","meta":["mammal","forests and fields of the Northern Hemisphere","the most widespread fox"],"description":"The most widely distributed member of the dog family, at home everywhere from deep forest to the edges of big cities. Its bushy tail helps it balance in mid-leap and covers its nose and paws while it sleeps in the cold. Its hearing is sharp enough to pick out small rodents moving under the snow.","fact":"A red fox locates a mouse by the rustle under the snow and leaps precisely, punching through the crust head first.","wiki_en":"Red fox"},{"name":"Fennec fox","emoji":"🏜️","meta":["mammal","deserts of North Africa","the smallest fox"],"description":"The smallest fox in the world, instantly known by ears far too big for its head, which shed excess heat in the desert and catch the faintest sound of prey under the sand. Thick fur on the soles protects it from scorching sand. It is mostly active at night, once the desert heat drops.","fact":"The fennec's huge ears work as natural air conditioning, carrying excess body heat away in the desert heat.","wiki_en":"Fennec fox"},{"name":"Arctic fox","emoji":"🧊","meta":["mammal","Arctic tundra","changes colour with the season"],"description":"A small fox of the tundra whose coat changes colour with the season: snow-white or bluish grey in winter, brown in summer to match bare ground. Dense fur and short legs, ears and muzzle help it hold on to warmth in the harsh Arctic cold. It tolerates some of the lowest temperatures of any predator.","fact":"The Arctic fox's winter coat is so dense that it can endure frosts well below minus thirty.","wiki_en":"Arctic fox"},{"name":"Raccoon","emoji":"🦝","meta":["mammal","forests of North America","a black mask on its face"],"description":"A nimble omnivore with a distinctive black mask around the eyes and extremely sensitive front paws that it uses to feel out and sort its food. It often dunks food in water, though scientists think this is about touch rather than washing. It has adapted well to living alongside people, cities included.","fact":"A raccoon's front paws are so sensitive that underwater it feels objects more precisely than it does on land.","wiki_en":"Raccoon"},{"name":"Badger","emoji":"🦡","meta":["mammal","forests and steppes of Eurasia","digs sprawling setts"],"description":"A nocturnal member of the weasel family, known for digging vast multi-level burrows called setts, which badger families use for decades and keep extending. The black and white stripes on its face serve as a warning to predators. The badger is omnivorous and puts on fat for a shallow winter sleep.","fact":"A badger sett can be used and enlarged by many generations of the same family over decades.","wiki_en":"European badger"},{"name":"Sea otter","emoji":"🦦","meta":["mammal","coasts of the North Pacific","uses stones as tools"],"description":"A marine otter that spends nearly its whole life in the water, sleep included, wrapping itself in kelp so the current does not carry it off. It is one of the few animals that use stones as tools, cracking shellfish open on its chest while floating on its back. The densest fur of any mammal keeps out the cold.","fact":"The sea otter has the densest fur of any mammal: tens of thousands of hairs grow on a single square centimetre of skin.","wiki_en":"Sea otter"},{"name":"Beaver","emoji":"🦫","meta":["mammal","rivers and lakes of the Northern Hemisphere","builds dams"],"description":"A large rodent famous for building dams and lodges that reshape whole river courses and create entire wetland ecosystems. Its powerful incisors never stop growing and are worn down on the wood it also eats through the winter. The flat scaly tail works as a rudder in water and a prop on land.","fact":"Beaver dams can grow so large that they are visible even in satellite images.","wiki_en":"Beaver"},{"name":"Hedgehog","emoji":"🦔","meta":["mammal","woods and gardens of Eurasia and Africa","spines for defence"],"description":"A small nocturnal animal covered by several thousand spines, modified hairs that serve as armour against predators. In danger it curls into a tight prickly ball using special muscles along its back. It is omnivorous, eating insects, slugs and carrion, which makes it a gardener's ally against pests.","fact":"A hedgehog may carry up to several thousand spines, each of which is replaced by a new one over time.","wiki_en":"Hedgehog"},{"name":"Squirrel","emoji":"🐿️","meta":["mammal","forests of Eurasia and North America","stores food for winter"],"description":"A nimble tree-dwelling rodent whose bushy tail steers its leaps between branches and doubles as a blanket in sleep. In autumn it hides nuts and seeds in countless caches, then forgets some of them, unwittingly helping the forest regrow. It does not hibernate, only slows down in hard frosts.","fact":"A squirrel comes down a trunk head first: its hind feet swivel backwards so the claws grip the bark.","wiki_en":"Squirrel"},{"name":"Moose","emoji":"🦌","meta":["mammal","forests of Eurasia and North America","the largest deer"],"description":"The largest living member of the deer family, unmistakable for the massive shovel-shaped antlers the males shed and regrow every year. Long legs let it move easily through deep snow and swamp. It swims well and will feed for a long time, ducking under for water plants.","fact":"A moose barely eats grass: it strips shoots, leaves and bark from trees and shrubs, browsing branches from above.","wiki_en":"Moose"},{"name":"Reindeer","emoji":"🛷","meta":["mammal","tundra and taiga of the Northern Hemisphere","females grow antlers too"],"description":"The only deer species in which females as well as males carry antlers. Broad cloven hooves work as snowshoes and as paddles when crossing rivers during migrations of many hundreds of kilometres. For the peoples of the far north the reindeer has been the main source of food, clothing and transport for centuries.","fact":"Come winter, reindeer eyes shift from gold to blue, which helps them see better in the polar twilight.","wiki_en":"Reindeer"},{"name":"Bison","emoji":"🦬","meta":["mammal","plains of North America","a symbol of the American prairie"],"description":"The largest land mammal of North America, once roaming the prairies in tens of millions before being all but wiped out in the nineteenth century. A massive head and a hump of muscle let it shovel snow aside to reach grass even in a hard winter. Today the species is recovering thanks to reserves and national parks.","fact":"For all its bulk a bison reaches about sixty kilometres an hour and easily outruns a human.","wiki_en":"Bison"},{"name":"Yak","emoji":"🐂","meta":["mammal","highlands of Central Asia","built for altitude"],"description":"A large shaggy bovine adapted to life at great altitude in the mountains of Tibet and nearby regions, where the air is thin and the cold is constant. Long dense hair and enlarged lungs and heart help it cope with the shortage of oxygen. For local peoples the yak has long supplied milk, wool, meat and muscle.","fact":"Yak milk is very rich, and in Tibet it is churned into the butter for traditional salted tea.","wiki_en":"Yak"},{"name":"Meerkat","emoji":"👀","meta":["mammal","deserts of southern Africa","lives in large groups"],"description":"A small member of the mongoose family that lives in large tight-knit groups with clear roles: some forage while others stand sentry, scanning for predators on the ground and in the air. The dark rings around its eyes work as natural sunglasses. Meerkats dig branching burrows that shelter the whole group.","fact":"Meerkats are not afraid of scorpions and teach their pups how to handle dangerous prey before eating it.","wiki_en":"Meerkat"},{"name":"Spotted hyena","emoji":"🦴","meta":["mammal","African savannah","the most powerful bite of any predator"],"description":"A large savannah carnivore with one of the strongest bites of any mammal, able to crush big bones to get at the marrow. It lives in close-knit clans dominated by females, who are usually larger and more aggressive than the males. Spotted hyenas are not only scavengers: they kill much of their own food.","fact":"The spotted hyena's piercing call sounds so much like laughter that it earned the animal the name laughing hyena.","wiki_en":"Spotted hyena"},{"name":"Porcupine","emoji":"🪡","meta":["mammal","Africa, Asia, the Americas","sharp defensive quills"],"description":"A large rodent covered in long sharp quills, modified hairs that serve as armour against predators. Threatened, a porcupine raises its quills, rattles its tail and can reverse straight into an attacker to drive them in. Contrary to the popular myth, it cannot shoot its quills at a distance.","fact":"Porcupine quills detach easily and stay in the attacker's body, while new ones grow in their place over time.","wiki_en":"Porcupine"},{"name":"Walrus","emoji":"🦭","meta":["mammal","Arctic coasts","long tusks"],"description":"A large pinniped known for long tusks, which both sexes grow and use for fighting, defence and hauling themselves out onto the ice. A thick layer of blubber shields it from Arctic cold, while stiff sensitive whiskers help it find shellfish on the seabed. Walruses gather in huge noisy haul-outs.","fact":"A walrus's tusks are greatly elongated upper canine teeth, and they keep growing throughout its life.","wiki_en":"Walrus"},{"name":"Bottlenose dolphin","emoji":"🐬","meta":["mammal","warm and temperate seas","one of the cleverest animals in the sea"],"description":"One of the best studied and most socially complex marine mammals, able to recognise itself in a mirror and using a unique signature whistle to identify itself to others. Bottlenose dolphins hunt and communicate in groups, coordinating elaborate strategies to herd fish. Underwater they navigate by echolocation.","fact":"A bottlenose dolphin sleeps by shutting down one half of its brain at a time; otherwise it would stop surfacing for air.","wiki_en":"Common bottlenose dolphin"},{"name":"Orca","emoji":"🐳","meta":["mammal","oceans worldwide","top of the marine food chain"],"description":"The largest member of the dolphin family and one of the ocean's foremost predators, hunting even large whales and sharks. It lives in stable family groups, each with its own set of calls passed down the generations. Different orca populations specialise in different prey, from fish to marine mammals.","fact":"In many orca pods the calves never leave their mother, staying by her side for their entire lives.","wiki_en":"Orca"},{"name":"Blue whale","emoji":"🐋","meta":["mammal","oceans worldwide","the largest animal on Earth"],"description":"The largest animal that has ever lived on Earth, outsizing even the biggest dinosaurs. It feeds mainly on krill, straining vast volumes of water through plates of baleen. For all its colossal size, the blue whale is entirely harmless to people.","fact":"The blue whale's call is among the loudest sounds in nature: a low rumble that travels many kilometres underwater.","wiki_en":"Blue whale"},{"name":"Humpback whale","emoji":"🎵","meta":["mammal","oceans worldwide","known for its songs"],"description":"A large baleen whale famous for the long, intricate songs males perform in the breeding season, which can carry dozens of kilometres underwater. It has enormous pectoral fins, up to a third of its body length, and puts on spectacular breaches. It makes some of the longest migrations of any mammal.","fact":"Humpback songs in one region change over time and spread to other populations, rather like a musical fashion.","wiki_en":"Humpback whale"},{"name":"Narwhal","emoji":"🦄","meta":["mammal","Arctic waters","a long spiral tusk"],"description":"An Arctic whale whose males carry a long spiralling tusk, which is really a greatly elongated left tooth growing out of the upper jaw. Because of that horn the narwhal was called the sea unicorn in the Middle Ages, and its tusks were sold as the horn of the legendary beast. It moves in small groups among the Arctic ice.","fact":"The narwhal has no dorsal fin: under Arctic ice it would only get in the way of surfacing at cracks for air.","wiki_en":"Narwhal"},{"name":"Beluga whale","emoji":"🤍","meta":["mammal","Arctic and subarctic waters","adults are pure white"],"description":"A small whale whose adults are pure white, while the calves are born grey and lighten with age. The beluga has a flexible neck, a rarity among whales, which lets it turn its head from side to side. It produces such a rich range of sounds that it is nicknamed the sea canary.","fact":"On its forehead the beluga has a mobile fatty melon whose shape it changes to aim its echolocation sounds.","wiki_en":"Beluga whale"},{"name":"Great white shark","emoji":"🦈","meta":["cartilaginous fish","oceans worldwide","the largest predatory fish"],"description":"The largest predatory fish in the world, able to sense the electric fields of living creatures through special organs on its snout. Despite the fearsome reputation the cinema gave it, attacks on people are extremely rare and usually accidental. It is one of the few fish that can keep its body warmer than the surrounding water.","fact":"A great white replaces its teeth all its life: each lost tooth is replaced by a new one from the rows behind.","wiki_en":"Great white shark"},{"name":"Hammerhead shark","emoji":"🔨","meta":["cartilaginous fish","warm seas worldwide","a hammer-shaped head"],"description":"A predatory shark with a flattened hammer-shaped head carrying its eyes and nostrils at the tips, which widens its field of view and sharpens its sense of smell. That head is also packed with electroreceptors that help it find prey buried in sand. It often hunts rays, pinning them to the bottom with its head.","fact":"Some hammerheads gather in large schools, although most sharks keep to themselves.","wiki_en":"Hammerhead shark"},{"name":"Whale shark","emoji":"🐳","meta":["cartilaginous fish","warm seas worldwide","the largest fish on Earth"],"description":"The largest living fish and, for all its colossal size, completely harmless to people, feeding on plankton and small fish. It strains huge volumes of water through its gills while cruising slowly near the surface. The pattern of pale spots on its skin is unique to each individual.","fact":"The spot pattern on a whale shark's skin is as individual as a fingerprint and is used by scientists to track animals.","wiki_en":"Whale shark"},{"name":"Manta ray","emoji":"🌊","meta":["cartilaginous fish","tropical and subtropical seas","the largest ray"],"description":"The largest of the rays, using broad triangular fins like wings to all but fly underwater. It feeds on plankton, funnelling it into its mouth with a pair of head lobes. The manta has a brain remarkably large for a fish, along with unusually complex behaviour.","fact":"In experiments mantas reacted oddly to their own reflection, and researchers took this as a possible sign of self-recognition.","wiki_en":"Manta ray"},{"name":"Octopus","emoji":"🐙","meta":["mollusc (cephalopod)","seas worldwide","eight arms with suckers"],"description":"A cephalopod with eight flexible arms studded with suckers, each arm partly run by a nervous system of its own. An octopus changes the colour and texture of its skin in an instant to match its surroundings, and counts as one of the cleverest invertebrates. It has three hearts and blue blood.","fact":"An octopus can squeeze through almost any gap its beak will pass, that beak being the only hard part of its body.","wiki_en":"Octopus"},{"name":"Seahorse","emoji":"🐴","meta":["fish","tropical and temperate seas","the male carries the young"],"description":"An odd fish with a horse-shaped head that swims upright, extremely slow and reliant on camouflage among the weeds. In seahorses it is the male that carries the brood: the female deposits her eggs into a pouch on his belly. Its tail grips like a monkey's and holds it steady on the coral.","fact":"The seahorse is one of the slowest swimmers among fish, moving by rapidly fluttering its small dorsal fin.","wiki_en":"Seahorse"},{"name":"Clownfish","emoji":"🐠","meta":["fish","reefs of the Indian and Pacific Oceans","lives among anemones"],"description":"A brightly coloured reef fish living in close symbiosis with anemones, whose stinging tentacles keep predators away while the fish cleans its host and brings it food. A special mucus on its skin protects it from the anemone's stinging cells. All are born male, and the largest fish in the group becomes female.","fact":"Clownfish larvae first drift in open water and only later go looking for an anemone of their own.","wiki_en":"Clownfish"},{"name":"Green sea turtle","emoji":"🐢","meta":["reptile","tropical and subtropical seas","returns to its home beach"],"description":"A large sea turtle that feeds mostly on algae and seagrass, which tints its fat greenish and gave the species its name. Females swim thousands of kilometres to lay their eggs on the very beach where they hatched themselves. The sex of the hatchlings depends on the temperature of the sand in the nest.","fact":"Resting on the bottom, a green turtle can go several hours without coming up for air.","wiki_en":"Green sea turtle"},{"name":"Nile crocodile","emoji":"🐊","meta":["reptile","rivers and lakes of Africa","one of the largest crocodiles"],"description":"One of the largest living crocodiles, able to lie motionless in ambush by the water for hours, waiting for animals to come and drink. It has one of the most powerful bites of any living creature, though the muscles that open its jaws are very weak. The female guards the nest closely and helps the hatchlings out of their eggs.","fact":"A female Nile crocodile carries her newly hatched young to the water in her mouth, holding them gently between her teeth.","wiki_en":"Nile crocodile"},{"name":"Komodo dragon","emoji":"🐉","meta":["reptile","islands of Indonesia","the largest lizard in the world"],"description":"The largest living lizard, able to hunt alone for prey far bigger than itself, deer and water buffalo included. Its saliva contains toxins that weaken a victim after the bite. It lives on only a handful of Indonesian islands, one of which gave the species its name.","fact":"A Komodo dragon can pick up the smell of carrion several kilometres away.","wiki_en":"Komodo dragon"},{"name":"Chameleon","emoji":"🦎","meta":["reptile","Africa, Madagascar, southern Europe","changes colour"],"description":"A tree-dwelling lizard famous for changing the colour of its skin, less for camouflage than for temperature control and signalling to others of its kind. Its eyes move independently, giving it an almost all-round view. Its long sticky tongue shoots out faster than an eye can blink to catch an insect.","fact":"A chameleon changes colour not with pigments but by rearranging a layer of tiny crystals in its skin that reflect light differently.","wiki_en":"Chameleon"},{"name":"Green iguana","emoji":"🦎","meta":["reptile","Central and South America","a large tree lizard"],"description":"A large arboreal lizard of the American tropics which, despite its name, shifts in shade from bright green to brownish and almost orange. A crest of sharp scales along its back and a long tail help it fend off predators and balance on branches. In danger it will leap into water from a great height and swim strongly.","fact":"The adult green iguana is almost entirely vegetarian, living on leaves, flowers and fruit.","wiki_en":"Green iguana"},{"name":"King cobra","emoji":"🐍","meta":["reptile","forests of South and Southeast Asia","the longest venomous snake"],"description":"The longest venomous snake in the world, able when threatened to raise the front third of its body and spread its distinctive hood. Unlike most snakes, the king cobra builds a nest of leaves for its eggs and guards it. It feeds mainly on other snakes, venomous ones included.","fact":"The king cobra is not a true cobra: it is placed in a genus of its own whose name means snake eater.","wiki_en":"King cobra"},{"name":"Green anaconda","emoji":"🐍","meta":["reptile","rivers and swamps of South America","one of the largest snakes in the world"],"description":"One of the heaviest snakes in the world, spending most of its life in the water of rivers and swamps, where its massive body is easier to carry. The anaconda is a boa, so it kills not with venom but by constriction, squeezing in the coils of its body. Females are markedly larger than males, unusually so even for snakes.","fact":"An anaconda's eyes and nostrils sit on top of its head, so it can breathe and watch for prey while almost entirely submerged.","wiki_en":"Green anaconda"},{"name":"Axolotl","emoji":"🐸","meta":["amphibian","lakes of Mexico","keeps its larval features for life"],"description":"A Mexican amphibian that normally never completes its metamorphosis, keeping its feathery external gills and aquatic life for good. It is famous for an extraordinary ability to regrow lost limbs, its tail and even parts of its internal organs. In the wild it survives only in the canals of Xochimilco in Mexico City and is critically endangered.","fact":"There are now far more axolotls in aquariums and laboratories than are left in the wild.","wiki_en":"Axolotl"},{"name":"Emperor penguin","emoji":"🐧","meta":["bird","coasts of Antarctica","the largest penguin"],"description":"The largest living penguin and the only one that breeds in the depth of the Antarctic winter, in extreme cold and wind. The male incubates the single egg on his feet for months without a break, covering it with a fold of skin while the female feeds at sea. The birds huddle in dense groups, taking turns on the coldest outer edge.","fact":"A male emperor penguin incubates the egg on his feet for about two months without eating, in the depth of the polar winter.","wiki_en":"Emperor penguin"},{"name":"Flamingo","emoji":"🦩","meta":["bird","salt lakes and lagoons","pink because of its diet"],"description":"A tall long-legged bird whose pink colour is not there at birth but comes from pigments in the shrimp and algae it eats. A flamingo can stand on one leg for a long time to conserve body heat, and it feeds upside down, straining water and mud through its curved bill. It lives in big noisy colonies on salt lakes and lagoons.","fact":"Flamingo chicks hatch grey and turn pink only as the pigments from their food build up.","wiki_en":"Flamingo"},{"name":"Peafowl","emoji":"🦚","meta":["bird","forests and gardens of South Asia","the male's magnificent train"],"description":"A bird famous for the male's huge fan of feathers, marked with the distinctive eyespots he spreads during courtship displays. Contrary to a common misconception, that magnificent train is not made of tail feathers but of greatly elongated upper tail coverts. Peahens are far plainer and choose a mate by the quality of his display.","fact":"As it shivers its open fan, a peacock produces infrasound that the human ear cannot hear.","wiki_en":"Peafowl"},{"name":"Toucan","emoji":"🐦","meta":["bird","forests of Central and South America","a huge bright bill"],"description":"A bird of the American rainforest with a bill far too big for its head, yet surprisingly light thanks to a spongy internal structure. The bill lets it reach fruit on thin branches and serves both as a status signal and as a radiator. Toucans nest in tree holes and often live in family groups.","fact":"To sleep, a toucan settles into a tree hollow, flips its tail over its back and tucks the huge bill under a wing.","wiki_en":"Toucan"},{"name":"Macaw","emoji":"🦜","meta":["bird","rainforests of South America","a large bright parrot"],"description":"A large brightly coloured parrot of the South American rainforest that can live to a great age and pairs for life. Its powerful curved beak cracks hard nuts and seeds that other birds cannot open. The macaw is one of the most recognisable emblems of the rainforest, yet many species have suffered badly from logging and trapping.","fact":"Thin lines of feathers run across the bare skin around a macaw's eyes, and that pattern differs from bird to bird.","wiki_en":"Macaw"},{"name":"Hummingbird","emoji":"🌺","meta":["bird","North and South America","the smallest bird"],"description":"A tiny bird of the New World, able to hover in mid-air by beating its wings dozens of times a second and even to fly backwards. The energy cost is so high that it feeds almost constantly, drawing nectar from flowers with its long bill. At night, to avoid starving, some species drop into a state close to torpor.","fact":"A hummingbird's heart can beat more than a thousand times a minute while it is in flight.","wiki_en":"Hummingbird"},{"name":"Bald eagle","emoji":"🦅","meta":["bird","North America","the national symbol of the USA"],"description":"A large bird of prey that became the national symbol of the United States thanks to its imposing look and the snow-white head adults grow only several years after hatching. It nests near large bodies of water and feeds mainly on fish, spotted from a great height. Its nests are among the largest structures any bird builds, reused year after year.","fact":"The bald eagle often robs other birds of their catch, which is why Benjamin Franklin once called it a bird of bad moral character.","wiki_en":"Bald eagle"},{"name":"Snowy owl","emoji":"🦉","meta":["bird","Arctic tundra","hunts by day and by night"],"description":"A large owl of the Arctic tundra with dense white plumage that hides it against the snow: almost pure white in males, flecked with dark bars in females. Unlike most owls it hunts by day as well as by night, adapted to the polar day and the polar night. Lemmings are the core of its diet, and its numbers rise and fall with theirs.","fact":"The snowy owl nests straight on the ground, scraping a hollow on a dry hummock in the open tundra.","wiki_en":"Snowy owl"},{"name":"Ostrich","emoji":"🏃","meta":["bird","African savannah","the largest and fastest-running bird"],"description":"The largest living bird, which gave up flight and became instead the fastest runner on two legs on the planet. Long powerful legs carry it at high speed and deliver kicks strong enough to drive off a predator. Ostriches lay the largest eggs of any bird alive today.","fact":"Contrary to the famous myth, an ostrich never buries its head in the sand when danger appears.","wiki_en":"Common ostrich"},{"name":"Swan","emoji":"🦢","meta":["bird","waters of Eurasia and North America","pairs for life"],"description":"A large water bird with a long flexible neck that often pairs for life and raises its young together with its partner. For all its graceful look, a swan can strike hard with a wing when defending its nest or cygnets. The several swan species differ in the shade of their plumage and the colour of the bill.","fact":"Its weight means a swan needs a runway: it patters a long way across the water before it can get airborne.","wiki_en":"Swan"},{"name":"Pelican","emoji":"🐦","meta":["bird","waters worldwide","an enormous throat pouch"],"description":"A large water bird with a capacious leathery pouch under its bill, used not for storage but for scooping up fish like a net. The pelican drains the water off before swallowing its catch. Some species hunt together, driving fish towards the shore or into the shallows in well-coordinated groups.","fact":"The brown pelican fishes differently: it plunges from a height, folding its wings just before it hits the water.","wiki_en":"Pelican"},{"name":"White stork","emoji":"🐦","meta":["bird","Europe, Africa, West Asia","a symbol of family and childbirth"],"description":"A large migratory bird with striking black and white plumage and a long red bill, nesting on roofs, poles and trees close to people. In Europe it has long stood for family and the arrival of children, which is where the legend of the stork delivering babies comes from. Each year it makes the long flight between Europe and Africa.","fact":"An adult white stork has almost no voice: it talks to its partner with loud clattering of the bill.","wiki_en":"White stork"},{"name":"Atlantic puffin","emoji":"🐧","meta":["bird","coasts of the North Atlantic","a bright multicoloured bill"],"description":"A small seabird with a bright triangular bill that takes on rich colours only for the breeding season and then partly moults away. The puffin swims and dives well, using its wings as paddles underwater, but flies and lands clumsily. It nests in colonies, in burrows on coastal cliffs and islands.","fact":"A puffin brings its chick a whole bouquet of small fish at once, holding them crosswise in its bill, sometimes a dozen at a time.","wiki_en":"Atlantic puffin"},{"name":"Kiwi","emoji":"🥝","meta":["bird","New Zealand","nostrils at the tip of the bill"],"description":"A flightless bird of New Zealand, about the size of a chicken, nocturnal and with a sense of smell unusually sharp for a bird. It is the only bird whose nostrils sit right at the tip of its long bill, which helps it sniff out worms and insects in the soil. The kiwi is a national symbol and gave New Zealanders their nickname.","fact":"Relative to its body size, the kiwi lays one of the largest eggs of any bird.","wiki_en":"Kiwi (bird)"},{"name":"Monarch butterfly","emoji":"🦋","meta":["insect","North and Central America","makes long migrations"],"description":"A large bright butterfly famous for one of the longest migrations of any insect: it flies thousands of kilometres to winter in Mexico. Monarch caterpillars eat nothing but milkweed, which is poisonous to many animals and makes the butterflies themselves inedible. The vivid orange and black is a warning to predators.","fact":"The monarch's round trip to Mexico takes several generations: no single butterfly flies the whole route.","wiki_en":"Monarch butterfly"},{"name":"Honey bee","emoji":"🐝","meta":["insect","worldwide except Antarctica","pollinates plants, makes honey"],"description":"A social insect living in large colonies where every individual has a clear role: workers, drones and a single fertile queen. Bees tell each other about the flowers they have found with a special dance that encodes the direction of the nectar and how far away it is. By pollinating plants the honey bee underpins agriculture across the planet.","fact":"A queen lives several years, while in summer a worker wears herself out in a matter of weeks of foraging.","wiki_en":"Western honey bee"},{"name":"Ladybird","emoji":"🐞","meta":["insect","worldwide","bright colours warn predators"],"description":"A small brightly coloured beetle whose spotted pattern warns predators of its foul taste and of the acrid fluid it releases from its leg joints when threatened. Most species are active hunters that eat thousands of aphids in a lifetime, which is why gardeners and farmers value them. The number of spots depends on the species, not the beetle's age.","fact":"Ladybirds overwinter in clusters, packing under bark and into crevices sometimes hundreds at a time.","wiki_en":"Coccinellidae"},{"name":"Praying mantis","emoji":"🙏","meta":["insect","warm regions worldwide","its distinctive praying pose"],"description":"A predatory insect named for the way it holds its grasping forelegs, as though folded in prayer. In truth those legs are a lightning weapon with which the mantis seizes prey in a fraction of a second. Its head can turn almost 180 degrees, which is a rarity among insects.","fact":"The mantis has a single ear on its thorax, tuned to the ultrasound of bats, its chief enemies in the dark.","wiki_en":"Mantis"},{"name":"Siberian Husky","emoji":"🐶","meta":["mammal (dog breed)","bred in northeastern Asia","sled dog, thick coat"],"description":"A sled breed developed by the Chukchi people for fast, durable hauling over long distances across snow. A dense double coat and blue, brown or mismatched eyes are the breed's calling card. Huskies are famously energetic and need hard physical work every day.","fact":"Huskies hardly bark: instead they howl and talk in long drawn-out grumbling sounds.","wiki_en":"Siberian Husky"},{"name":"Welsh Corgi","emoji":"🐕","meta":["mammal (dog breed)","bred in Wales","short legs, long body"],"description":"A small herding breed from Wales with famously short legs and a long body, bred originally to drive cattle. Corgis nipped at the cows' heels and dodged the kicks easily because they stood so low. The breed became known worldwide partly through Queen Elizabeth II's devotion to it.","fact":"There are two separate corgi breeds: the Pembroke with a very short tail and the Cardigan with a long bushy one.","wiki_en":"Pembroke Welsh Corgi"},{"name":"Golden Retriever","emoji":"🦮","meta":["mammal (dog breed)","bred in Scotland","a friendly companion breed"],"description":"A breed developed in nineteenth-century Scotland to retrieve shot game, hence the soft mouth that can carry a bird without damaging it. The golden retriever is renowned for a friendly, patient temperament, which often makes it a guide dog and a family companion. Its thick golden coat needs regular grooming.","fact":"The breed was created by the Scottish Lord Tweedmouth, who crossed retrievers with the now extinct Tweed Water Spaniel.","wiki_en":"Golden Retriever"},{"name":"German Shepherd","emoji":"🐕‍🦺","meta":["mammal (dog breed)","bred in Germany","a working and service breed"],"description":"One of the most widespread working breeds in the world, developed in Germany in the late nineteenth century for herding and later taken up by police, military and rescue services. It is known for its intelligence, trainability and devotion to its handler. That versatility also makes it a frequent film star and guide dog.","fact":"The breed standard was set in the late 1800s by the German officer Max von Stephanitz, who began from a single male named Horand.","wiki_en":"German Shepherd"},{"name":"Maine Coon","emoji":"🐈","meta":["mammal (cat breed)","bred in the USA (Maine)","one of the largest cat breeds"],"description":"One of the largest domestic cat breeds, from the American state of Maine, where a thick coat and big paws helped it through severe winters. Its ear tufts and bushy tail give it something of a lynx's look. For all its size, the Maine Coon is known for a gentle, sociable nature and a quiet, almost chirping voice.","fact":"The Maine Coon is the official state cat of Maine, where the breed comes from.","wiki_en":"Maine Coon"},{"name":"Sphynx cat","emoji":"🙀","meta":["mammal (cat breed)","bred in Canada","virtually hairless"],"description":"A cat breed distinguished by the near-total absence of fur, though the skin often carries a barely visible down that feels like suede. With no coat, the sphynx feels the cold and seeks warmth, and its skin gets grubby quickly and needs frequent bathing. The breed was developed in Canada in the later twentieth century from a natural mutation.","fact":"Calling the breed hypoallergenic is a mistake: allergies are caused by proteins in a cat's saliva and skin, not by the fur itself.","wiki_en":"Sphynx cat"},{"name":"Cougar","emoji":"🐾","meta":["mammal","North and South America","up to 100 kg"],"description":"One of the most widely distributed wild cats on the planet, found from Canada all the way to Patagonia. Unlike the lion or the tiger it cannot roar, but it is a superb jumper and climber. It goes by a whole string of local names: puma, mountain lion, panther.","fact":"A cougar can leap up to six metres from a standing start.","wiki_en":"Cougar"},{"name":"Caracal","emoji":"🐈","meta":["mammal","Africa and Asia","around 10 to 20 kg"],"description":"A slender desert cat with the long black ear tufts that give it its unmistakable look. The caracal is an outstanding jumper and can knock birds out of the air in mid-flight. Its name comes from a Turkic phrase meaning black ear.","fact":"A caracal can jump more than three metres into the air to catch a bird in flight.","wiki_en":"Caracal"},{"name":"African wild dog","emoji":"🐕","meta":["mammal","African savannah","up to 30 kg"],"description":"An African predator with a mottled coat that is unique to each animal, like a fingerprint. It lives in large packs with a clear hierarchy and hunts more successfully than almost any other predator. It is an endangered species, its range shrinking year by year.","fact":"The African wild dog has only four toes on each front foot, which sets it apart from every other member of the dog family.","wiki_en":"African wild dog"},{"name":"Golden jackal","emoji":"🐺","meta":["mammal","Africa, Asia, Europe","around 10 kg"],"description":"A smallish member of the dog family that usually lives in pairs and holds the same territory for years. It is omnivorous and undemanding, which lets it settle easily near people and their farms. In the folklore of many nations the jackal plays the cunning, sly rogue.","fact":"Jackal pairs usually stay together for life and guard one and the same territory side by side.","wiki_en":"Golden jackal"},{"name":"Coyote","emoji":"🐺","meta":["mammal","North and Central America","around 15 kg"],"description":"A supple, wary predator that has spread across the whole of North America thanks to sheer adaptability. It eats almost anything, from rodents to fruit, which helps it survive even inside cities. In the cultures of Native America the coyote often appears as a cunning trickster.","fact":"Coyotes frequently settle in large cities, including the outskirts of Los Angeles and Chicago.","wiki_en":"Coyote"},{"name":"Dingo","emoji":"🐕","meta":["mammal","Australia","around 15 to 20 kg"],"description":"A feral dog that reached Australia thousands of years ago with people and became the continent's chief land predator. Unlike domestic dogs the dingo rarely barks, howling and yowling instead. To protect the sheep country, Australia built one of the longest fences in the world.","fact":"Australia's dingo fence runs for thousands of kilometres and counts as one of the longest structures of its kind in the world.","wiki_en":"Dingo"},{"name":"Fallow deer","emoji":"🦌","meta":["mammal","forests of Europe","males up to 100 kg"],"description":"An elegant deer with flat palmate antlers in the males and a spotted summer coat much like a fawn's. It lives in herds and prefers open broadleaf woods and parkland. For centuries it was kept in the hunting grounds of the European nobility.","fact":"Unlike a red deer's antlers, a fallow deer's are broad and shovel-shaped at the tips.","wiki_en":"Fallow deer"},{"name":"Red deer","emoji":"🦌","meta":["mammal","forests of Europe and Asia","males up to 250 kg"],"description":"One of the largest deer species, whose males shed and regrow their branching antlers every year. In the autumn rut the stags give out a loud bellowing roar that draws hinds and warns off rivals. It has a long-standing place in hunting tradition and in heraldry.","fact":"A red deer's antlers grow back from scratch every year and can weigh several kilograms.","wiki_en":"Red deer"},{"name":"Roe deer","emoji":"🦌","meta":["mammal","forests of Europe and Asia","up to 30 kg"],"description":"A small graceful deer with short antlers in the males and a distinctive pale patch on its rump. The roe deer is equally at home in woodland and open fields, and often comes out to feed along the forest edge at dusk. It is one of the most common hoofed animals in Eurasia.","fact":"Alarmed, a roe deer lets out a sharp clipped bark much like a dog's.","wiki_en":"Roe deer"},{"name":"Wild boar","emoji":"🐗","meta":["mammal","forests of Eurasia and North Africa","up to 150 kg"],"description":"The ancestor of the domestic pig, a sturdy omnivore with coarse bristles and sharp tusks in the males. It lives in groups led by the oldest female and has a famously good nose for finding roots and acorns. Being prolific and adaptable, it has spread across many continents.","fact":"Every breed of domestic pig descends from the wild boar, domesticated several thousand years ago.","wiki_en":"Wild boar"},{"name":"Muskox","emoji":"🐂","meta":["mammal","Arctic tundra","up to 400 kg"],"description":"A powerful shaggy animal built for the Arctic tundra thanks to a dense many-layered coat. When predators appear, muskoxen form a tight ring with their horns facing out and the calves inside. Despite the name it is closer to goats and sheep than to cattle.","fact":"The muskox's underwool, called qiviut, is reckoned one of the warmest and lightest fibres in the world.","wiki_en":"Muskox"},{"name":"Tapir","emoji":"🐽","meta":["mammal","South America and Asia","up to 300 kg"],"description":"A large herbivore with a short flexible proboscis that it uses to pull down leaves and young shoots. It looks a little like a pig, but its closest relatives are horses and rhinos. Young tapirs are born striped and spotted, which helps them hide in the undergrowth.","fact":"A tapir's proboscis is its nose and upper lip fused together, feeling out branches and drawing leaves to its mouth.","wiki_en":"Tapir"},{"name":"Manatee","emoji":"🦭","meta":["mammal","warm waters of the Atlantic","up to 500 kg"],"description":"A slow-moving aquatic mammal with a rounded body and flippers instead of forelegs, spending almost its whole life in shallow warm water. It eats nothing but water plants, getting through up to a tenth of its own weight a day. It is one of the likely originals behind the mermaid legends.","fact":"A manatee's teeth are replaced all its life: worn front teeth drop out and new ones move forward from the back of the jaw.","wiki_en":"Manatee"},{"name":"Dugong","emoji":"🦭","meta":["mammal","warm waters of the Indian and Pacific Oceans","up to 400 kg"],"description":"A marine herbivore and close relative of the manatee, but with a forked tail fluke like a whale's. It grazes on seagrass in the shallows, which is why it is sometimes called the sea cow. Because it breeds so slowly it counts as a vulnerable species.","fact":"The dugong is the only surviving species of its family: its closest relative, Steller's sea cow, was hunted to extinction.","wiki_en":"Dugong"},{"name":"Seal","emoji":"🦭","meta":["mammal","seas and oceans","from 40 to 3,000 kg"],"description":"A pinniped mammal superbly equipped for cold water by a thick layer of blubber. On land it moves awkwardly, but underwater it is swift and can dive to great depths. The group covers a great many species, from the small ringed seal to the huge elephant seal.","fact":"Some seal species can hold their breath underwater for tens of minutes during a deep dive.","wiki_en":"Earless seal"},{"name":"Sea lion","emoji":"🦭","meta":["mammal","Pacific coasts","from 100 kg to 1 tonne"],"description":"A pinniped with small external ear flaps, which set it apart from true seals, and the knack of moving nimbly on its flippers ashore. Sea lions train easily, which is why they so often perform in aquariums. They gather on the shore in large, noisy haul-outs.","fact":"Sea lions can prop themselves on their front flippers and walk on land, so they climb even steep rocks and breakwaters.","wiki_en":"Sea lion"},{"name":"Northern fur seal","emoji":"🦭","meta":["mammal","the North Pacific","up to 270 kg"],"description":"A pinniped with a dense double-layered pelt that was hunted for centuries and very nearly brought the species to extinction. Like sea lions it has small external ears and can prop itself on its flippers to walk ashore. In the breeding season the males hold large harems on the rookeries.","fact":"A fur seal's pelt is so dense that water never reaches the skin: a layer of air trapped in the underfur keeps it warm.","wiki_en":"Northern fur seal"},{"name":"Eurasian otter","emoji":"🦦","meta":["mammal","rivers and lakes of Eurasia","around 10 kg"],"description":"An agile member of the weasel family, splendidly suited to life in water by webbed toes and a dense waterproof coat. It feeds mainly on fish and hunts fast and with evident relish. It is known for playfulness: young otters love to slide down chutes of mud or snow.","fact":"Otters slide down riverbanks on their bellies into the water purely for the fun of it, not for hunting.","wiki_en":"Eurasian otter"},{"name":"Least weasel","emoji":"🐾","meta":["mammal","woods and fields of Eurasia and the Americas","up to 250 g"],"description":"The smallest hunter in the weasel family, with a long supple body that lets it chase rodents right into their burrows. For all its tiny size the weasel is famously bold and will attack prey noticeably bigger than itself. In winter some populations turn white.","fact":"Its metabolism runs so fast that a weasel has to eat several times a day; it cannot go hungry for long.","wiki_en":"Least weasel"},{"name":"Stoat","emoji":"🐾","meta":["mammal","forests and tundra of the Northern Hemisphere","around 300 g"],"description":"A small, quicksilver predator whose snow-white winter fur with a black tail tip was prized for centuries as a mark of royal power and purity. In summer its coat is reddish brown, which hides it in the grass. It hunts mainly rodents, running them down even inside narrow burrows.","fact":"The stoat's white winter fur with black tail tips has long trimmed the robes of European monarchs.","wiki_en":"Stoat"},{"name":"Marten","emoji":"🐾","meta":["mammal","forests of Eurasia","around 1.5 kg"],"description":"A nimble forest hunter of the weasel family, moving freely through the treetops in pursuit of squirrels and birds. It is omnivorous: besides small animals it will happily eat berries and the honey of wild bees. Marten fur has long been a staple of the fur trade.","fact":"A marten can leap several metres from tree to tree and barely needs to come down to the ground.","wiki_en":"Marten"},{"name":"Sable","emoji":"🐾","meta":["mammal","Siberian taiga","around 1.5 kg"],"description":"An animal of the Siberian taiga whose thick silky fur has been reckoned for centuries among the most valuable in the world. It lives secretively, hunting small rodents and birds, but will not turn down pine nuts and berries. Sable trapping was once a major source of revenue for the Russian state.","fact":"Because it was worth so much, sable fur was historically called the soft gold of Siberia.","wiki_en":"Sable"},{"name":"Polecat","emoji":"🐾","meta":["mammal","Eurasia","around 1 to 2 kg"],"description":"A smallish hunter of the weasel family with a long supple body and a famously sharp smell, released by its glands when it is frightened. Its domesticated form, the ferret, has been kept as a pet for several centuries. In the wild the polecat hunts mainly rodents and rabbits.","fact":"Domestic ferrets have been kept as pets for several hundred years.","wiki_en":"European polecat"},{"name":"Skunk","emoji":"🦨","meta":["mammal","North and South America","around 3 to 5 kg"],"description":"A small black and white animal famous for its main defence: the acrid, foul-smelling fluid it sprays from its glands when threatened. Before spraying, a skunk usually warns its enemy by stamping its feet and arching its back. The vivid contrasting pattern is itself a warning to predators.","fact":"A skunk's spray can see off even a bear, and people can smell it several hundred metres away.","wiki_en":"Skunk"},{"name":"Virginia opossum","emoji":"🐀","meta":["mammal","North and South America","around 2 to 5 kg"],"description":"The only marsupial that lives naturally in North America, known for its extreme response to danger: playing dead. The opossum is omnivorous, climbs trees well and grips branches with its tail. As in other marsupials, the young finish developing in their mother's pouch.","fact":"Badly frightened, an opossum involuntarily drops into a faint-like state, mimicking death.","wiki_en":"Virginia opossum"},{"name":"Mole","emoji":"🐾","meta":["mammal","fields and woods of Eurasia","around 100 g"],"description":"An underground dweller with powerful shovel-like paws and all but useless eyes, made up for by sharp hearing and touch. The mole digs complex tunnel systems and feeds mainly on earthworms, which it stores up for later. Small as it is, it can dig tens of metres of tunnel in a day.","fact":"A mole can eat almost its own body weight in food over a single day.","wiki_en":"European mole"},{"name":"Bat","emoji":"🦇","meta":["mammal","almost every continent","from a few grams to 1 kg"],"description":"The only mammal capable of true powered flight, thanks to membranes stretched between its elongated fingers. Most species find their way in the dark by echolocation, sending out ultrasonic calls and catching the echo. Depending on the species they live on insects, nectar or fruit.","fact":"With echolocation a bat can pick out an insect the size of a mosquito in complete darkness.","wiki_en":"Bat"},{"name":"Hamster","emoji":"🐹","meta":["mammal","steppes of Eurasia","around 100 to 150 g"],"description":"A small rodent with capacious cheek pouches in which it carries stores of grain and seeds back to its burrow. In the wild it lives alone and defends its territory fiercely, while the domestic species have long been popular pets. It is a compulsive hoarder, stockpiling food in astonishing quantities.","fact":"Almost every domestic Syrian hamster descends from one single family of animals caught in Syria in the 1930s.","wiki_en":"Hamster"},{"name":"Guinea pig","emoji":"🐹","meta":["mammal","native to South America","around 1 kg"],"description":"A domesticated rodent, first bred by the peoples of the Andes and now a popular pet in many countries. Despite the name it has nothing to do with pigs or with Guinea; the name probably came from the sea route by which the animals reached Europe. It lives in groups and chatters away in a range of sounds.","fact":"Guinea pigs communicate by whistling and purring, and when delighted they hop on the spot, a move nicknamed popcorning.","wiki_en":"Guinea pig"},{"name":"Chinchilla","emoji":"🐭","meta":["mammal","the Andes of South America","around 500 g"],"description":"A small rodent with one of the densest coats of any mammal: a whole bundle of hairs grows from every single follicle. It lives high in the mountains, where that thick coat keeps out the cold. Its valuable fur once drove the wild population almost to extinction.","fact":"Chinchillas never bathe in water, since such thick fur takes far too long to dry; they clean themselves by rolling in fine volcanic dust.","wiki_en":"Chinchilla"},{"name":"Raven","emoji":"🐦‍⬛","meta":["bird","most of the Northern Hemisphere","around 1.2 kg"],"description":"One of the cleverest birds in the world, able to solve difficult logical puzzles and to use simple tools. Ravens recognise individual human faces and remember them for a long time. In the myths of many peoples the raven appears now as a wise messenger, now as an omen of doom.","fact":"A raven can recognise particular human faces and remember them for years.","wiki_en":"Common raven"},{"name":"Owl","emoji":"🦉","meta":["bird","almost every continent","from 30 g to 4 kg"],"description":"A night hunter that flies almost silently thanks to a special feather structure that muffles the sound of its wingbeats. An owl's huge eyes cannot move in their sockets, so it can turn its head almost 270 degrees instead. In many cultures the owl stands for wisdom.","fact":"Because its eyes cannot move, an owl can turn its head almost three quarters of the way round.","wiki_en":"Owl"},{"name":"Eagle","emoji":"🦅","meta":["bird","almost every continent","up to 9 kg in the largest species"],"description":"A large bird of prey with exceptionally sharp sight that lets it spot quarry from a great height. Eagles build massive nests and often return to the same site year after year. It has long stood for strength and power on the coats of arms and flags of many nations.","fact":"An eagle's eyesight is several times sharper than a human's, which lets it pick out prey from an enormous height.","wiki_en":"Eagle"},{"name":"Peregrine falcon","emoji":"🦅","meta":["bird","almost every continent","around 0.5 to 1.5 kg"],"description":"A bird of prey recognised as the fastest living creature on the planet, thanks to the stoop it makes on its quarry from a great height. It hunts mainly other birds, catching them in that headlong dive. The peregrine adapts well to cities and often nests on tall buildings.","fact":"In its stoop the peregrine reaches a speed no other living creature on Earth can match.","wiki_en":"Peregrine falcon"},{"name":"Hawk","emoji":"🦅","meta":["bird","woods and fields of Eurasia and the Americas","around 1 kg"],"description":"A bird of prey with short broad wings suited to sharp turns between the trees of dense woodland. It hunts mainly other birds, taking them from ambush. The goshawk has been used in falconry alongside the true falcons since ancient times.","fact":"A hawk's short rounded wings let it manoeuvre brilliantly between tree trunks while hunting.","wiki_en":"Hawk"},{"name":"Vulture","emoji":"🦅","meta":["bird","Africa, Asia, Europe","up to 10 kg"],"description":"A large scavenger with a wingspan of several metres, able to soar for hours on rising air while scanning for dead animals. Its bald head helps it stay clean while feeding on a carcass. Acting as nature's sanitary service, vultures keep disease from spreading.","fact":"Vultures can make out the carcass of a dead animal from a height of several kilometres.","wiki_en":"Old World vulture"},{"name":"Turkey","emoji":"🦃","meta":["bird","native to North America","up to 10 kg"],"description":"A large domestic bird, domesticated by the peoples of Mesoamerica long before the Europeans arrived. The males are known for their courtship gobbling and for fanning out their tail like a peacock. In the United States turkey is the traditional dish at Thanksgiving.","fact":"The bare skin on a turkey's head and neck shifts from pale to bright blue and red depending on how worked up the bird is.","wiki_en":"Turkey (bird)"},{"name":"Chicken","emoji":"🐔","meta":["bird","domesticated worldwide","around 2 to 3 kg"],"description":"The most numerous domestic bird in the world, raised for meat and eggs for several thousand years already. The ancestor of the modern chicken is taken to be the wild red junglefowl of Southeast Asia. Chickens have complex social lives with a strict hierarchy in the flock, the pecking order.","fact":"The phrase pecking order, used for hierarchy in any group, came from watching hens do exactly that.","wiki_en":"Chicken"},{"name":"Duck","emoji":"🦆","meta":["bird","waters worldwide","around 1 to 1.5 kg"],"description":"A water bird with a broad flat bill and webbed feet, equally at home swimming and flying. A duck's feathers are dressed with oil from a special gland, so they hardly take up water at all. Many duck species have been domesticated and are raised for meat, eggs and down.","fact":"Oil from the preen gland makes a duck's plumage practically waterproof.","wiki_en":"Duck"},{"name":"Goose","emoji":"🪿","meta":["bird","waters of the Northern Hemisphere","around 3 to 5 kg"],"description":"A large water bird known for its vigilance and for the loud cackling it sets up when strangers appear, which is why geese were long kept as a kind of alarm system. Wild geese make long seasonal flights in tight wedges. It was domesticated very early for meat, down and eggs.","fact":"By legend, geese once saved Rome with their cackling, waking the guards before a night attack.","wiki_en":"Goose"},{"name":"House sparrow","emoji":"🐦","meta":["bird","almost worldwide","around 30 g"],"description":"A small darting bird that has lived side by side with people in towns and villages around the world for ages. Sparrows keep to flocks, squabble noisily over food and grow used to people easily. For all their modest size they are bold and pushy in character.","fact":"Sparrows take dust baths, bathing in sand or dust to clean their feathers.","wiki_en":"House sparrow"},{"name":"Woodpecker","emoji":"🐦","meta":["bird","forests of Eurasia and the Americas","around 100 to 300 g"],"description":"A forest bird with a stout straight bill that it uses to chisel bark in search of insect larvae and to hollow out nest holes. A special skull structure and a long flexible tongue shield its brain from the shock of all that hammering. Its drumming on a trunk is a signal to other birds of its kind.","fact":"A woodpecker's tongue is so long that it wraps around the inside of the skull and anchors near the base of the bill.","wiki_en":"Woodpecker"},{"name":"Common cuckoo","emoji":"🐦","meta":["bird","forests of Eurasia and Africa","around 100 g"],"description":"A bird famous for brood parasitism: many cuckoo species slip their eggs into other birds' nests and leave the raising of the chicks to somebody else. Once hatched, the cuckoo chick often shoves the host's eggs and nestlings out of the nest. The male's distinctive spring call gave the cuckoo clock its name.","fact":"Over a single summer a female cuckoo manages to plant eggs in more than a dozen different nests.","wiki_en":"Common cuckoo"},{"name":"Gull","emoji":"🐦","meta":["bird","sea and river coasts worldwide","around 1 kg"],"description":"A bird of coasts and lakes that takes easily to living next to people and often makes a living around harbours and rubbish tips. Gulls fly and swim well, and some species crack shellfish by dropping them from a height onto rocks. They often keep to large noisy colonies on the shore.","fact":"Gulls can drink seawater: special glands above the eyes flush the excess salt out of the body.","wiki_en":"Gull"},{"name":"Crane","emoji":"🐦","meta":["bird","marshes and steppes of Eurasia and the Americas","around 5 to 7 kg"],"description":"A large migratory bird with long legs and a long neck, known for its spectacular courtship dances full of leaps and beating wings. Cranes fly high in a wedge, calling out with loud bugling cries. In many cultures the crane stands for faithfulness and long life.","fact":"The crane's courtship dance includes synchronised leaps, bows and the tossing of twigs or grass into the air.","wiki_en":"Crane (bird)"},{"name":"Tuna","emoji":"🐟","meta":["fish","warm and temperate ocean waters","up to several hundred kg"],"description":"A large fast open-water fish that can hold its body temperature above that of the surrounding sea thanks to a special arrangement of its blood vessels. Tuna make long migrations across entire oceans in search of food. It is one of the most heavily fished species in the world and especially prized in Japanese cooking.","fact":"Some tuna species can accelerate to a speed comparable to that of a small motorboat.","wiki_en":"Tuna"},{"name":"Salmon","emoji":"🐟","meta":["fish","northern seas and rivers","up to 10 to 20 kg"],"description":"A fish famous for its migrations: it is born in fresh water, grows up at sea, then returns to spawn in the very place where it hatched. The way to the spawning ground often runs against a strong current and involves leaping up rapids. Salmon is one of the world's great commercial fish.","fact":"A salmon can find its way back to the exact river where it hatched, using its sense of smell along with other senses.","wiki_en":"Salmon"},{"name":"Trout","emoji":"🐟","meta":["fish","rivers and lakes of Eurasia and the Americas","around 1 to 2 kg"],"description":"A freshwater fish of the salmon family that favours the cold clean water of mountain rivers and lakes. Its colouring varies widely with where it lives, from plain silver to a mottled coat with vivid spots. It is popular both for fish farming and for angling.","fact":"Trout in a river is taken as a sign of clean water, since the fish is sensitive to pollution.","wiki_en":"Trout"},{"name":"Pike","emoji":"🐟","meta":["fish","rivers and lakes of Eurasia and the Americas","up to 20 to 30 kg"],"description":"A predatory freshwater fish with a long body and a mouth full of sharp teeth, lying in ambush among the water plants. It is famously voracious and will attack prey almost as large as itself. The pike turns up in many Russian folk tales, among them one in which it granted wishes.","fact":"In a Russian folk tale a magic pike granted Yemelya every wish he asked for.","wiki_en":"Northern pike"},{"name":"Common carp","emoji":"🐟","meta":["fish","rivers and lakes of Eurasia","up to 20 kg"],"description":"A freshwater fish and one of the first to be domesticated for rearing in ponds, back in antiquity. It is undemanding, omnivorous and able to survive in water with little oxygen. Its ornamental form, the koi, is prized in Japan for its brilliant colouring.","fact":"Ornamental koi carp can live for several decades if they are well looked after.","wiki_en":"Common carp"},{"name":"Wels catfish","emoji":"🐟","meta":["fish","rivers and lakes of Eurasia","up to 100 kg and more"],"description":"A large scaleless freshwater fish with long sensitive barbels around its mouth that help it find prey in murky water. It lives mainly on the bottom and by night, hiding by day in deep pools and among sunken wood. It is one of the biggest freshwater predators in Europe.","fact":"A catfish's barbels are studded with taste receptors and let it find prey by touch in total darkness.","wiki_en":"Wels catfish"},{"name":"Piranha","emoji":"🐟","meta":["fish","rivers of South America","around 1 kg"],"description":"A small freshwater fish with sharp triangular teeth, which owes its reputation as a ferocious killer largely to popular culture. In reality most piranha species live mainly on other fish, carrion and plants, and attacks on people are extremely rare. They keep to shoals in the rivers of the Amazon basin.","fact":"Contrary to the popular myth, mass piranha attacks on people are extremely rare and happen only in unusual circumstances.","wiki_en":"Piranha"},{"name":"Ray","emoji":"🐟","meta":["fish","seas and oceans worldwide","from a few kg to 2 tonnes"],"description":"A flat cartilaginous fish, a relative of the sharks, moving with smooth wavelike beats of its broadened pectoral fins. Many rays hide on the bottom by burying themselves in sand, and some can generate an electric discharge for defence and hunting. The largest species, the manta, spans almost seven metres.","fact":"The manta, the largest of the rays, can have a fin span of almost seven metres.","wiki_en":"Batoidea"},{"name":"Barracuda","emoji":"🐟","meta":["fish","warm seas and oceans","up to 1.5 to 2 m"],"description":"A fast predatory fish with a long body and a row of sharp teeth, formidable enough in appearance to unnerve divers. Despite that look, attacks on people are rare and usually linked to murky water or to shiny objects. It hunts other fish in short explosive rushes.","fact":"A barracuda is sometimes drawn to a swimmer's shiny jewellery, which it may mistake for a small fish.","wiki_en":"Barracuda"},{"name":"Electric eel","emoji":"⚡","meta":["fish","rivers of the Amazon basin","up to 2.5 m and 20 kg"],"description":"A freshwater fish able to generate a powerful electric discharge with special organs that take up most of its body. The discharge serves for hunting and defence and also for finding its way in murky water. Despite the name, it is closer to the catfishes than to true eels.","fact":"An electric eel can generate a discharge of several hundred volts.","wiki_en":"Electric eel"},{"name":"Dragonfly","emoji":"🐉","meta":["insect","waters worldwide","a few centimetres"],"description":"A predatory insect with two pairs of transparent wings, each moving independently, which makes the dragonfly an extraordinarily agile flier. Its larvae spend up to several years in the water before turning into the winged adult. It belongs to one of the oldest orders of flying insects on Earth.","fact":"A dragonfly can fly not only forwards but backwards, and can hover on the spot almost like a helicopter.","wiki_en":"Dragonfly"},{"name":"Bush cricket","emoji":"🦗","meta":["insect","meadows and fields worldwide","a few centimetres"],"description":"A jumping insect with powerful hind legs that carry it many times its own body length in a single leap. Its distinctive chirping is made by rubbing the wing covers against each other, not with its mouth. It feeds mostly on plants, with the occasional small insect.","fact":"The chirping sound comes from rubbing special parts of the wings together, not from any voice.","wiki_en":"Tettigoniidae"},{"name":"Locust","emoji":"🦗","meta":["insect","steppes, deserts and fields on several continents","a few centimetres"],"description":"A grasshopper that under certain conditions switches from a solitary form to a swarming one and gathers into gigantic travelling swarms. Such invasions can strip crops across enormous areas in a matter of days. Accounts of locust plagues appear in texts from the deepest antiquity.","fact":"A locust swarm covering a square kilometre eats as much greenery in a day as tens of thousands of people would need.","wiki_en":"Locust"},{"name":"Ant","emoji":"🐜","meta":["insect","almost worldwide","a few millimetres"],"description":"A social insect living in colonies many thousands strong, with a clear hierarchy and a division of labour among the workers. Ants can carry loads many times their own weight and build elaborate underground structures together. They form one of the most widespread and numerous groups of insects on Earth.","fact":"Some ant species can lift and carry loads dozens of times heavier than they are.","wiki_en":"Ant"},{"name":"Wasp","emoji":"🐝","meta":["insect","almost worldwide","around 1 to 2 cm"],"description":"A stinging insect with the familiar yellow and black colouring that warns predators off. Unlike a bee, a wasp can sting again and again, because its sting does not stay behind in the victim's skin. Many wasp species are predators and help keep other insect pests in check.","fact":"A wasp's sting, unlike a bee's, is smooth and does not lodge in the skin, so the wasp can sting many times over.","wiki_en":"Wasp"},{"name":"Bumblebee","emoji":"🐝","meta":["insect","temperate Northern Hemisphere","around 1 to 3 cm"],"description":"A large furry insect of the bee family, able to fly even in cool weather because it can warm up its flight muscles before taking off. Bumblebees are important pollinators, above all in cold climates where other insects are less active. They live in small colonies, unlike the great hives of honey bees.","fact":"Before taking off in cool weather, a bumblebee shivers its thoracic muscles to warm its body up.","wiki_en":"Bumblebee"},{"name":"Cockroach","emoji":"🪳","meta":["insect","almost worldwide","a few centimetres"],"description":"One of the oldest and most tenacious of insects, able to survive in the most varied conditions thanks to sheer adaptability and modest needs. Some species have become companions of humanity, moving into houses in search of food and warmth. It is famous for how much punishment it can take.","fact":"A cockroach can go a long time without food and endure considerable damage to its body.","wiki_en":"Cockroach"},{"name":"Mosquito","emoji":"🦟","meta":["insect","almost worldwide","a few millimetres"],"description":"A small flying insect whose females feed on blood, which they need to develop their eggs, while the males live on nectar. Mosquitoes breed in standing water and in some parts of the world carry dangerous diseases. The familiar whine comes from the rapid beat of their wings.","fact":"A mosquito's whine is the sound of its wingbeat frequency, which differs between males and females.","wiki_en":"Mosquito"},{"name":"Spider","emoji":"🕷️","meta":["arthropod","almost worldwide","from a fraction of a mm to 30 cm across the legs"],"description":"An arthropod rather than an insect, with eight legs and, in many species, the ability to weave trapping webs out of silk. Spider silk is one of the strongest materials in nature: weight for weight it beats steel. Nearly all spiders are venomous, but only a handful of species are dangerous to people.","fact":"Science knows more than fifty thousand species of spider, and almost all of them are predators.","wiki_en":"Spider"},{"name":"Scorpion","emoji":"🦂","meta":["arthropod","warm regions of almost the whole world","a few centimetres"],"description":"An ancient arthropod with its trademark pincers and a curved tail tipped with a venomous sting. It is mostly active at night and hides from the heat by day under stones or in burrows. Under ultraviolet light a scorpion's shell glows, which is how people find them after dark.","fact":"Under an ultraviolet lamp a scorpion's shell glows a bluish green.","wiki_en":"Scorpion"},{"name":"Labrador Retriever","emoji":"🐕","meta":["mammal","dog breed","up to 35 kg"],"description":"One of the most popular dog breeds in the world: its ancestors helped fishermen in Newfoundland, and in Britain they were developed into a gundog retriever. It is known for a friendly temperament, intelligence and a love of water and of fetching. Labradors are often trained as guide dogs and rescue dogs.","fact":"Thanks to their calm nature and trainability, labradors are one of the most widely used guide dog breeds.","wiki_en":"Labrador Retriever"},{"name":"Dachshund","emoji":"🐕","meta":["mammal","dog breed","up to 12 kg"],"description":"A German breed with its trademark long body and short legs, bred originally to hunt badgers and other animals in their burrows. Its German name is made of the words for badger and dog. Compact as it is, it is bold and famously stubborn.","fact":"The breed's German name translates literally as badger dog, which is exactly what it was bred to hunt.","wiki_en":"Dachshund"},{"name":"Beagle","emoji":"🐕","meta":["mammal","dog breed","around 10 to 15 kg"],"description":"An English hound with one of the keenest noses of any dog, long used in small packs to hunt hare by scent. Its friendly, energetic character has made the beagle a popular family dog. That same nose often puts beagles to work in customs and border control.","fact":"Because their sense of smell is so exceptional, beagles are often used to sniff out banned goods in passengers' luggage.","wiki_en":"Beagle"},{"name":"Dalmatian","emoji":"🐕","meta":["mammal","dog breed","around 25 to 30 kg"],"description":"A breed with an unmistakable white coat marked in black or brown spots, which only appear several weeks after birth: the puppies are born pure white. Historically dalmatians were kept at stables and fire stations as dogs that ran with the carriages. The breed became famous worldwide largely thanks to the Disney films.","fact":"Dalmatian puppies are born completely white, and their trademark spots come out only after a few weeks.","wiki_en":"Dalmatian (dog)"},{"name":"Chihuahua","emoji":"🐕","meta":["mammal","dog breed","up to 3 kg"],"description":"The smallest dog breed in the world, named after the Mexican state its ancestors came from. Tiny as it is, the chihuahua has a bold, self-assured and sometimes downright pugnacious character. The breed became a celebrity favourite as a fashionable companion.","fact":"The chihuahua is named after the Mexican state of Chihuahua, where its likely ancestors were found.","wiki_en":"Chihuahua (dog)"},{"name":"Rottweiler","emoji":"🐕","meta":["mammal","dog breed","up to 60 kg"],"description":"A German breed of large muscular dogs whose ancestors, by the usual account, marched with the Roman legions and were later used by German butchers to drive cattle. It is known for strength, confidence and devotion to its owner when properly raised. Today it works as a service and guard dog.","fact":"The breed is named after the German town of Rottweil, where butchers traditionally kept rottweilers.","wiki_en":"Rottweiler"},{"name":"Dobermann","emoji":"🐕","meta":["mammal","dog breed","around 35 to 45 kg"],"description":"A German breed developed in the late nineteenth century by the tax collector Karl Dobermann, who needed reliable protection on his rounds. It has a lean silhouette, a quick mind and an unusual readiness to learn. It is widely used as a service, guard and tracking dog.","fact":"The breed carries the name of its creator, the tax collector Karl Friedrich Louis Dobermann.","wiki_en":"Dobermann"},{"name":"Poodle","emoji":"🐩","meta":["mammal","dog breed","from 2 to 30 kg"],"description":"A breed with a thick curly coat, bred originally to hunt waterfowl and retrieve them from the water. The famous sculpted clip once had a practical point: it made swimming easier while leaving the joints and chest insulated. The poodle is reckoned one of the brightest of all dog breeds.","fact":"The poodle's famous sculpted clip was practical to begin with, making it easier to swim in cold water.","wiki_en":"Poodle"},{"name":"Persian cat","emoji":"🐈","meta":["mammal","cat breed","around 4 to 6 kg"],"description":"One of the oldest domestic cat breeds, with long thick fur and a characteristically flat face. Persians are calm and sedentary by nature and need careful grooming on a regular basis. The breed became known in Europe centuries ago through merchants who brought cats back from the East.","fact":"Because the fur is so long, Persian cats need daily brushing, or the coat mats into tangles.","wiki_en":"Persian cat"},{"name":"Siamese cat","emoji":"🐈","meta":["mammal","cat breed","around 3 to 5 kg"],"description":"A breed with an elegant body and the familiar colourpoint pattern: dark face, ears, paws and tail against a pale body. It comes from Thailand, where it was historically held sacred and kept at temples and at the royal court. Siamese cats are known for a loud, talkative voice and a sociable nature.","fact":"The dark markings on a Siamese cat's face, ears and paws depend on body temperature: the cooler the spot, the darker the fur.","wiki_en":"Siamese cat"},{"name":"Bengal cat","emoji":"🐆","meta":["mammal","cat breed","around 4 to 7 kg"],"description":"A breed created by crossing the domestic cat with the Asian leopard cat, hence the vivid spotted or marbled coat that recalls a wild cat. For all those wild roots in the pedigree, today's bengals are fully domestic and have a playful, energetic character. The breed is comparatively young, taking shape in the later twentieth century.","fact":"The bengal cat's spotted pattern comes from its wild ancestor, the Asian leopard cat.","wiki_en":"Bengal cat"},{"name":"British Shorthair","emoji":"🐈","meta":["mammal","cat breed","around 4 to 8 kg"],"description":"A solid, stocky breed with dense plush fur and a round face, one of the oldest cat breeds of the British Isles. The classic colour is a bluish grey, although many other coats are recognised. It is known for a calm, independent and even-tempered nature.","fact":"The bluish grey coat that became the breed's calling card is still often called simply British blue.","wiki_en":"British Shorthair"},{"name":"Scottish Fold","emoji":"🐈","meta":["mammal","cat breed","around 3 to 6 kg"],"description":"A breed with distinctive forward-folded ears, the result of a natural genetic mutation first noticed on a Scottish farm in the 1960s. A round face and large eyes give the cat an unmistakably good-natured look. The same mutation carries a risk of cartilage problems, so breeding calls for caution.","fact":"Every fold-eared Scottish cat descends from a single cat named Susie, found on a farm in Scotland.","wiki_en":"Scottish Fold"},{"name":"Russian Blue","emoji":"🐈","meta":["mammal","cat breed","around 3 to 5.5 kg"],"description":"An elegant breed with a short dense bluish grey coat and vivid green eyes, which by one account came from the northern port towns of Russia. It is reserved but devoted, and quiet-voiced. The breed is recognised by cat fancier organisations around the world.","fact":"The double coat of a Russian Blue feels like soft plush or sealskin to the touch.","wiki_en":"Russian Blue"},{"name":"Ragdoll","emoji":"🐈","meta":["mammal","cat breed","around 4 to 9 kg"],"description":"A large breed with semi-long fur and blue eyes, developed in the United States in the 1960s and named for its habit of going completely limp in its owner's arms. It is calm, affectionate and easy-going. It is one of the largest domestic cat breeds.","fact":"The breed's name means rag doll, after its way of flopping and relaxing in a person's arms.","wiki_en":"Ragdoll"}];
